WITH RankedPosts AS (SELECT p.Id AS PostId, p.Title, p.CreationDate, p.ViewCount, p.Score, p.AnswerCount, ROW_NUMBER() OVER (PARTITION BY p.OwnerUserId ORDER BY p.CreationDate DESC NULLS FIRST) AS UserRank, p.OwnerUserId FROM Posts AS p JOIN Users AS u ON p.OwnerUserId = u.Id WHERE p.PostTypeId = 1 AND u.Reputation > 1000), UserBadges AS (SELECT b.UserId, COUNT(b.Id) AS BadgeCount, GROUP_CONCAT(b.Name, ', ') AS BadgeNames FROM Badges AS b WHERE b.Class = 1 GROUP BY b.UserId), PostComments AS (SELECT c.PostId, COUNT(c.Id) AS CommentCount FROM Comments AS c GROUP BY c.PostId) SELECT rp.Title, rp.CreationDate, COALESCE(ub.BadgeCount, 0) AS GoldBadgeCount, COALESCE(pc.CommentCount, 0) AS Comments, rp.ViewCount, rp.Score, CASE WHEN rp.ViewCount IS NULL THEN 'No Views' ELSE CAST(rp.ViewCount AS Nullable(String)) END AS ViewCountText, CASE WHEN rp.AnswerCount > 0 THEN 'Has Answers' ELSE 'No Answers' END AS AnswerStatus, CASE WHEN rp.Score > 0 THEN 'Positive Score' WHEN rp.Score < 0 THEN 'Negative Score' ELSE 'Neutral Score' END AS ScoreStatus FROM RankedPosts AS rp LEFT JOIN UserBadges AS ub ON rp.OwnerUserId = ub.UserId LEFT JOIN PostComments AS pc ON rp.PostId = pc.PostId WHERE rp.UserRank = 1 ORDER BY rp.CreationDate DESC NULLS FIRST FETCH FIRST 50 ROWS ONLY